const listeners: Record<string, Function[]> = {};
let demoBlocked = false;
// Grup sohbeti test harness'i - gercek sunucu yok, bu yuzden olusturulan
// gruplar sadece bu modul-seviyesi Map'te (oturum boyunca) tutulur (bkz.
// server/src/group.ts - GERCEK backend'in demo'su).
const demoGroups = new Map<string, { id: string; name: string; avatarUrl: string | null; members: any[]; messages: any[] }>();
let demoGroupCounter = 0;
// useConnectionQuality.ts'in "ping:rtt" olcumunu test edebilmek icin -
// gercek sunucu yok, bu yuzden donus suresini burada SIMULE ediyoruz.
// 50 => iyi, 200 => orta, 450 => zayif (bkz. useConnectionQuality.ts esikleri).
let simulatedPingDelayMs = 50;
const fakeSocket: any = {
  id: "demo-socket-id",
  emit: (event: string, payload: any, cb?: any) => {
    if (typeof payload === "function") cb = payload;
    if (event === "dm:open" && cb) cb({ ok: true, messages: MESSAGES, expiresAfterMs: null });
    else if (event === "dm:list" && cb) {
      cb({
        ok: true,
        conversations: [
          {
            conversationId: "c1",
            peerId: PEER_ID,
            peerName: "Ayşe Yılmaz",
            peerHandle: "ayseyilmaz",
            peerAvatarUrl: null,
            lastMessage: { text: "Hangisini aldın peki", createdAt: now - 50, fromUserId: MY_ID },
            unread: true,
            unreadCount: 2,
            isFriend: true,
            pinned: true,
            muted: false,
            archived: false,
          },
          {
            conversationId: "c2",
            peerId: "u2",
            peerName: "Mehmet Demir",
            peerHandle: "mehmetdemir",
            peerAvatarUrl: null,
            lastMessage: { text: "Yarın müsait misin?", createdAt: now - 1000 * 60 * 60 * 3, fromUserId: "u2" },
            unread: false,
            unreadCount: 0,
            isFriend: true,
            pinned: false,
            muted: false,
            archived: false,
          },
          {
            conversationId: "c3",
            peerId: "u3",
            peerName: "Zeynep Kaya",
            peerHandle: "zeynepkaya",
            peerAvatarUrl: null,
            lastMessage: { text: "🎵 sunset-drive.mp3", createdAt: now - 1000 * 60 * 60 * 26, fromUserId: "u3" },
            unread: false,
            unreadCount: 0,
            isFriend: true,
            pinned: false,
            muted: true,
            archived: false,
          },
        ],
      });
    }
    else if (event === "friend:status" && cb) cb({ ok: true, status: demoBlocked ? "blocked" : "none" });
    else if (event === "friend:block" && cb) {
      demoBlocked = true;
      cb({ ok: true });
    } else if (event === "friend:unblock" && cb) {
      demoBlocked = false;
      cb({ ok: true });
    } else if (event === "friends:list" && cb) {
      cb({ ok: true, friends: DEMO_FRIENDS, incoming: [], blocked: [], recentRoommates: [] });
    } else if (event === "dm:sendContact" && cb) {
      const shared = DEMO_FRIENDS.find((f) => f.userId === payload?.sharedUserId);
      cb({
        ok: true,
        message: {
          id: `contact-${Date.now()}`,
          fromUserId: MY_ID,
          fromName: "Ben",
          text: `👤 ${shared?.name ?? "Kullanıcı"}`,
          replyTo: null,
          createdAt: Date.now(),
          expiresAt: null,
          kind: "contact",
          sharedUserId: shared?.userId ?? payload?.sharedUserId,
          sharedUserName: shared?.name ?? "Kullanıcı",
          sharedUserHandle: shared?.handle ?? null,
          sharedUserAvatarUrl: shared?.avatarUrl ?? null,
        },
      });
    } else if (event === "dm:sendPoll" && cb) {
      cb({
        ok: true,
        message: {
          id: `poll-${Date.now()}`,
          fromUserId: MY_ID,
          fromName: "Ben",
          text: `📊 ${payload?.question ?? ""}`,
          replyTo: null,
          createdAt: Date.now(),
          expiresAt: null,
          kind: "poll",
          pollQuestion: payload?.question ?? "",
          pollOptions: payload?.options ?? [],
          pollOptionImages: payload?.optionImages ?? null,
          pollVotes: new Array((payload?.options ?? []).length).fill(0),
          myPollVote: null,
        },
      });
    } else if (event === "dm:votePoll" && cb) {
      // Gercek sunucu "en fazla 2 oy" dongusunu simule edemeyiz (fake socket
      // tek tarafli) - sadece bu TEK oyu 1 olarak sayip ack'liyoruz, GORSEL
      // oy-verme etkilesimini (secili secenegin vurgulanmasi) test etmek icin yeterli.
      const n = payload?.optionIndex != null ? payload.optionIndex + 1 : 1;
      const votes = new Array(Math.max(n, 3)).fill(0);
      if (payload?.optionIndex != null) votes[payload.optionIndex] = 1;
      cb({ ok: true, votes });
    } else if (event === "dm:send" && cb) {
      cb({
        ok: true,
        message: {
          id: `text-${Date.now()}`,
          fromUserId: MY_ID,
          fromName: "Ben",
          text: payload?.text ?? "",
          mediaUrl: null,
          isAdult: false,
          replyTo: payload?.replyTo ?? null,
          createdAt: Date.now(),
          expiresAt: null,
          kind: "text",
        },
      });
    } else if (event === "dm:sendSticker" && cb) {
      cb({
        ok: true,
        message: {
          id: `sticker-${Date.now()}`,
          fromUserId: MY_ID,
          fromName: "Ben",
          text: "🏷️ Çıkartma",
          mediaUrl: payload?.mediaUrl ?? null,
          isAdult: false,
          replyTo: null,
          createdAt: Date.now(),
          expiresAt: null,
          kind: "sticker",
          stickerId: payload?.stickerId ?? null,
        },
      });
    } else if (event === "dm:sendVideo" && cb) {
      cb({
        ok: true,
        message: {
          id: `video-${Date.now()}`,
          fromUserId: MY_ID,
          fromName: "Ben",
          text: payload?.caption ?? "",
          mediaUrl: payload?.mediaUrl ?? null,
          isAdult: false,
          replyTo: null,
          createdAt: Date.now(),
          expiresAt: null,
          kind: "video",
        },
      });
    } else if (event === "dm:preview" && cb) {
      cb({ ok: false });
    } else if (event === "group:create" && cb) {
      demoGroupCounter += 1;
      const id = `demo-group-${demoGroupCounter}`;
      const members = [
        { userId: MY_ID, name: "Ben", handle: null, avatarUrl: null },
        ...DEMO_FRIENDS.filter((f) => (payload?.memberIds || []).includes(f.userId)),
      ];
      const group = { id, name: payload?.name || "", avatarUrl: null, members, messages: [] };
      demoGroups.set(id, group);
      cb({ ok: true, group: { id: group.id, name: group.name, avatarUrl: group.avatarUrl } });
    } else if (event === "group:setAvatar" && cb) {
      const group = demoGroups.get(payload?.groupId);
      if (group) group.avatarUrl = payload?.avatarUrl ?? null;
      cb({ ok: true });
    } else if (event === "group:list" && cb) {
      cb({
        ok: true,
        groups: Array.from(demoGroups.values()).map((g) => ({
          groupId: g.id,
          name: g.name,
          avatarUrl: g.avatarUrl,
          lastMessage: g.messages[g.messages.length - 1] ?? null,
        })),
      });
    } else if (event === "group:open" && cb) {
      const group = demoGroups.get(payload?.groupId);
      if (!group) return cb({ ok: false });
      // DIKKAT: "messages: group.messages" (AYNI referans) GroupChatScreen'in
      // React state'ine o anki demo dizisini DOGRUDAN atardi - sonraki
      // "group:send" buna push() yapinca state'i SESSIZCE (React'in
      // haberi olmadan) mutate edip ayni mesajin IKI KEZ eklenmesine (bir
      // mutasyonla, bir de setMessages'in kendi ekleyisiyle) yol aciyordu.
      // Kopyasi (immutable) verilir.
      cb({ ok: true, group: { id: group.id, name: group.name, avatarUrl: group.avatarUrl, members: group.members }, messages: [...group.messages] });
    } else if (event === "group:send" && cb) {
      const group = demoGroups.get(payload?.groupId);
      if (!group) return cb({ ok: false });
      const message = {
        id: `demo-group-msg-${Date.now()}`,
        groupId: group.id,
        fromUserId: MY_ID,
        fromName: "Ben",
        text: payload?.text || "",
        createdAt: Date.now(),
      };
      group.messages.push(message);
      cb({ ok: true, message });
    } else if (event === "group:sendImage" && cb) {
      const group = demoGroups.get(payload?.groupId);
      if (!group) return cb({ ok: false });
      const message = {
        id: `demo-group-msg-${Date.now()}`,
        groupId: group.id,
        fromUserId: MY_ID,
        fromName: "Ben",
        text: payload?.caption || "📷 Fotoğraf",
        createdAt: Date.now(),
        kind: "photo",
        mediaUrl: payload?.mediaUrl ?? null,
        isAdult: false,
      };
      group.messages.push(message);
      cb({ ok: true, message });
    } else if (event === "group:sendVoice" && cb) {
      const group = demoGroups.get(payload?.groupId);
      if (!group) return cb({ ok: false });
      const message = {
        id: `demo-group-msg-${Date.now()}`,
        groupId: group.id,
        fromUserId: MY_ID,
        fromName: "Ben",
        text: "🎤 Sesli mesaj",
        createdAt: Date.now(),
        kind: "voice",
        mediaUrl: payload?.mediaUrl ?? null,
        durationMs: payload?.durationMs ?? null,
      };
      group.messages.push(message);
      cb({ ok: true, message });
    } else if (event === "ping:rtt" && cb) {
      setTimeout(() => cb(Date.now()), simulatedPingDelayMs);
    } else if (cb) cb({ ok: true });
  },
  on: (event: string, fn: Function) => {
    listeners[event] = listeners[event] || [];
    listeners[event].push(fn);
  },
  off: (event: string, fn: Function) => {
    listeners[event] = (listeners[event] || []).filter((f) => f !== fn);
  },
};
(socketService as any).getSocket = () => fakeSocket;
setTimeout(() => {
  (listeners["dm:seen"] || []).forEach((fn) => fn({ byUserId: PEER_ID, at: now - 1000 * 60 * 10 }));
}, 800);

const fakeChain = {
  select: () => fakeChain,
  eq: () => fakeChain,
  maybeSingle: async () => ({ data: { default_reaction_emoji: "❤️", avatar_url: null }, error: null }),
};
// "supabase" named export'u canli bir getter oldugu icin tum binding'i
// DEGISTIREMEYIZ ("Cannot set property supabase of #<Object> which has
// only a getter") - bunun yerine GERCEK objenin kendi alanlarini (auth/from)
// yerinde degistiriyoruz.
(supabaseService.supabase as any).auth = {
  getUser: async () => ({ data: { user: { id: MY_ID } } }),
  getSession: async () => ({ data: { session: { access_token: "fake-token", user: { id: MY_ID } } } }),
};
(supabaseService.supabase as any).from = () => fakeChain;
// FriendsScreen.tsx handleCreateGroup'un grup fotografi yukleme adimi icin -
// gercek bir "avatars" bucket'i yok, bu yuzden her zaman basarili donup
// sabit bir demo URL'i veriyor.
(supabaseService.supabase as any).storage = {
  from: () => ({
    upload: async () => ({ error: null }),
    getPublicUrl: () => ({ data: { publicUrl: "https://picsum.photos/seed/demogroup/200" } }),
  }),
};

export default function DevHarness() {
  const [screen, setScreen] = useState<"dm" | "info" | "incoming" | "list" | "group" | "groupInfo">("dm");
  const [activeGroup, setActiveGroup] = useState<any>(null);
  const [groupInfoDetail, setGroupInfoDetail] = useState<any>(null);
  const [infoProps, setInfoProps] = useState<any>(null);
  const [callActive, setCallActive] = useState(false);
  const [callIsVideo, setCallIsVideo] = useState(false);
  const [callMinimized, setCallMinimized] = useState(false);
  const [callState, setCallState] = useState({ connected: false, elapsed: 0 });
  const [callMuted, setCallMuted] = useState(false);
  const [callSpeakerOn, setCallSpeakerOn] = useState(false);
  // Uygulama icindeyken gelen arama bildirimi - henuz cevaplanmamis,
  // tam ekran IncomingCallScreen yerine bu kucuk banner gorunuyor.
  const [incomingBannerActive, setIncomingBannerActive] = useState(false);
  const [addCallVisible, setAddCallVisible] = useState(false);
  const [bluetoothAvailable, setBluetoothAvailable] = useState(false);
  const [peerSharingScreen, setPeerSharingScreen] = useState(false);
  const [peerSharingScreenVertical, setPeerSharingScreenVertical] = useState(false);
  // "Arama Ekle" ile ucuncu+ kisi eklenince GroupCallGrid'e gecsin diye -
  // undefined = normal 1'e 1 ekran (varsayilan), 1+ eleman = grup modu.
  const [groupParticipants, setGroupParticipants] = useState<GroupParticipant[] | undefined>(undefined);
  const peer = { userId: PEER_ID, name: "Ayşe Yılmaz", handle: "ayseyilmaz" };

  // useCallback ile SABIT referans - inline verilirse VoiceCallScreen'deki
  // onStateChange useEffect'i her render'da yeniden tetiklenip sonsuz
  // render donguusune girip tiklama olaylarini kacirmaya basliyordu
  // (konsolda "Maximum update depth exceeded" hatasi - kullanicinin fark
  // ettigi "hoparlor/mikrofon bazen tiklamaya tepki vermiyor" sorununun
  // asil nedeni buydu).
  const handleCallStateChange = useCallback((connected: boolean, elapsed: number) => {
    setCallState({ connected, elapsed });
  }, []);

  function handleCallEnd() {
    setCallActive(false);
    setCallMinimized(false);
    setCallMuted(false);
    setCallSpeakerOn(false);
    setScreen("info");
  }

  return (
    <SafeAreaProvider>
      <View style={{ flex: 1 }}>
        <AppBackground />
        {incomingBannerActive ? (
          <MinimizedCallBanner
            name={peer.name}
            avatarUrl={infoProps?.peerAvatarUrl ?? null}
            incoming
            callTypeLabel="Sesli arama"
            onPress={() => {
              setIncomingBannerActive(false);
              setScreen("incoming");
            }}
            onAccept={() => {
              setIncomingBannerActive(false);
              setCallActive(true);
              setCallMinimized(false);
              setScreen("info");
            }}
            onDecline={() => setIncomingBannerActive(false)}
            onMessage={() => {
              setIncomingBannerActive(false);
              setScreen("dm");
            }}
          />
        ) : (
          callActive &&
          callMinimized && (
            <MinimizedCallBanner
              name={peer.name}
              avatarUrl={infoProps?.peerAvatarUrl ?? null}
              elapsedLabel={callState.connected ? formatElapsed(callState.elapsed) : "Çalıyor..."}
              onPress={() => setCallMinimized(false)}
              muted={callMuted}
              onToggleMute={() => setCallMuted((m) => !m)}
              speakerOn={callSpeakerOn}
              onToggleSpeaker={() => setCallSpeakerOn((s) => !s)}
              onEndCall={handleCallEnd}
            />
          )
        )}
        <View
          style={{
            flex: 1,
            marginTop: incomingBannerActive || (callActive && callMinimized) ? -36 : 0,
          }}
        >
          {screen === "list" ? (
            // DMListScreen useFocusEffect (react-navigation) kullaniyor -
            // harness'in GERISI NavigationContainer'siz calistigi icin
            // sadece bu dal icin ekleniyor.
            <NavigationContainer>
              <DMListScreen
                onOpenDM={() => setScreen("dm")}
                onOpenGroup={(group) => {
                  setActiveGroup(group);
                  setScreen("group");
                }}
              />
            </NavigationContainer>
          ) : screen === "group" ? (
            <GroupChatScreen
              group={activeGroup}
              onBack={() => setScreen("list")}
              onOpenInfo={(detail) => {
                setGroupInfoDetail(detail);
                setScreen("groupInfo");
              }}
            />
          ) : screen === "groupInfo" ? (
            <GroupInfoScreen
              readOnly
              members={groupInfoDetail?.members ?? []}
              groupName={groupInfoDetail?.name ?? ""}
              onChangeGroupName={() => {}}
              groupAvatarUri={groupInfoDetail?.avatarUrl ?? ""}
              onChangeGroupAvatarUri={() => {}}
              onBack={() => setScreen("group")}
            />
          ) : screen === "dm" ? (
            <DMScreen
              peer={peer}
              onBack={() => setScreen("list")}
              onOpenInfo={(info: any) => {
                setInfoProps(info);
                setScreen("info");
              }}
            />
          ) : screen === "info" ? (
            <DmInfoScreen
              peer={peer}
              peerAvatarUrl={infoProps?.peerAvatarUrl ?? null}
              muted={infoProps?.muted ?? false}
              mediaMessages={MESSAGES.filter((m) => !!m.mediaUrl) as any}
              fileMessages={infoProps?.fileMessages ?? []}
              onShowInChat={infoProps?.onShowInChat ?? (() => {})}
              onToggleMute={infoProps?.onToggleMute ?? (() => {})}
              onBack={() => setScreen("dm")}
              onBlocked={() => setScreen("dm")}
              onStartVoiceCall={() => {
                setCallActive(true);
                setCallMinimized(false);
              }}
            />
          ) : (
            <IncomingCallScreen
              peer={peer}
              peerAvatarUrl={infoProps?.peerAvatarUrl ?? null}
              onAccept={() => {
                setCallActive(true);
                setCallMinimized(false);
                setScreen("info");
              }}
              onDecline={() => setScreen("dm")}
            />
          )}
        </View>

        {callActive && (
          <View
            style={[StyleSheet.absoluteFill, callMinimized && styles.hiddenCallLayer]}
            pointerEvents={callMinimized ? "none" : "auto"}
          >
            {callIsVideo ? (
              <VideoCallScreen
                peer={peer}
                peerAvatarUrl={infoProps?.peerAvatarUrl ?? null}
                onEnd={handleCallEnd}
                onMinimize={() => setCallMinimized(true)}
                onStateChange={handleCallStateChange}
                muted={callMuted}
                onToggleMute={() => setCallMuted((m) => !m)}
                speakerOn={callSpeakerOn}
                onToggleSpeaker={() => setCallSpeakerOn((s) => !s)}
                onAddCall={() => setAddCallVisible(true)}
                bluetoothAvailable={bluetoothAvailable}
                peerSharingScreen={peerSharingScreen}
                peerSharingScreenVertical={peerSharingScreenVertical}
                myAvatarUrl="data:image/svg+xml;base64,"
                myName="Ben"
                participants={groupParticipants}
              />
            ) : (
              <VoiceCallScreen
                peer={peer}
                peerAvatarUrl={infoProps?.peerAvatarUrl ?? null}
                onEnd={handleCallEnd}
                onMinimize={() => setCallMinimized(true)}
                onStateChange={handleCallStateChange}
                muted={callMuted}
                onToggleMute={() => setCallMuted((m) => !m)}
                speakerOn={callSpeakerOn}
                onToggleSpeaker={() => setCallSpeakerOn((s) => !s)}
                onAddCall={() => setAddCallVisible(true)}
                onSwitchToVideo={() => setCallIsVideo(true)}
              />
            )}
          </View>
        )}
        <Modal
          visible={addCallVisible}
          animationType="slide"
          onRequestClose={() => setAddCallVisible(false)}
          statusBarTranslucent
        >
          <FriendsScreen
            onBack={() => setAddCallVisible(false)}
            onOpenDM={() => {}}
            onOpenParticipant={() => {}}
            inviteMode
            hideInviteExtras
            excludeUserIds={[peer.userId]}
            onSendInvites={() => setAddCallVisible(false)}
          />
        </Modal>
        <CustomAlertHost />
      </View>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  hiddenCallLayer: { opacity: 0 },
});
